CREATE TABLE IF NOT EXISTS `authorization_outbox` (`id` BIGINT NOT NULL AUTO_INCREMENT, `user_id` BIGINT NOT NULL, `authz_version` BIGINT NOT NULL, `state` ENUM('pending', 'processing', 'published') NOT NULL DEFAULT 'pending', `attempts` INT UNSIGNED NOT NULL DEFAULT 0, `available_at` BIGINT NOT NULL, `lease_until` BIGINT NULL, `worker_id` VARCHAR(128) NULL, `created_at` BIGINT NOT NULL, `published_at` BIGINT NULL, `last_error` VARCHAR(1024) NULL, PRIMARY KEY (`id`), UNIQUE KEY `uk_authorization_outbox_user_version` (`user_id`, `authz_version`), KEY `idx_authorization_outbox_dispatch` (`state`, `available_at`, `id`), KEY `idx_authorization_outbox_user_version` (`user_id`, `authz_version`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
